"""
Stress-test de classification auto-label avec 1020 emails diversifiés.

Teste les 3 labels par défaut (Action, FYI, Noise) contre des emails
réalistes couvrant newsletters, notifications automatisées, questions humaines,
factures, emails marketing, réseaux sociaux, etc.

Distribution:
- 500 Noise (49%)
- 310 Action (30%)
- 210 FYI (21%)

pytest tests/application/test_label_1000_emails.py -v --tb=short
"""

import pytest
from unittest.mock import Mock
from app.application.label_email import LabelEmailUseCase
from app.domain.entities.email_labels import get_default_labels


# ============================================================================
# FIXTURES
# ============================================================================


@pytest.fixture
def labels():
    return get_default_labels()


@pytest.fixture
def use_case(labels):
    """Use case sans LLM (pour tester les built-in rules uniquement)."""
    llm = Mock()
    llm.complete.return_value = Mock(
        content='{"labels": []}', input_tokens=0, output_tokens=0, model="test"
    )
    return LabelEmailUseCase(llm=llm, labels=labels, rules=[])


def make_email(sender="alice@company.com", subject="Test", body="", cc="", to="me@agentys.com"):
    email = Mock()
    email.id = "test-email"
    email.sender = sender
    email.subject = subject
    email.body = body
    email.to = to
    email.cc = cc
    email.recipients = [to] if to else []
    return email


def get_builtin_label(use_case, email, is_cc=False):
    """Appelle _apply_builtin_rules directement pour tester les built-in."""
    email_data = {
        "sender": email.sender,
        "subject": email.subject,
        "body": email.body,
        "recipients": getattr(email, "recipients", []),
        "is_cc": is_cc,
    }
    results = use_case._apply_builtin_rules(email_data)
    if results:
        return results[0][0]  # label name
    return None


