# ============================================================================
# PARAMETERIZED TESTS
# ============================================================================


@pytest.mark.parametrize(
    "sender,subject,body,expected_label,description",
    NOISE_EMAILS,
    ids=[e[4] for e in NOISE_EMAILS],
)
def test_noise_classification(use_case, sender, subject, body, expected_label, description):
    """Noise emails should be classified as Noise."""
    email = make_email(sender=sender, subject=subject, body=body)
    label = get_builtin_label(use_case, email)
    assert label == expected_label, (
        f"[{description}] Expected '{expected_label}' but got '{label}' "
        f"for sender='{sender}', subject='{subject[:50]}'"
    )


@pytest.mark.parametrize(
    "sender,subject,body,expected_label,description",
    ACTION_EMAILS,
    ids=[e[4] for e in ACTION_EMAILS],
)
def test_action_classification(use_case, sender, subject, body, expected_label, description):
    """Action emails should be classified as Action."""
    email = make_email(sender=sender, subject=subject, body=body)
    label = get_builtin_label(use_case, email)
    assert label == expected_label, (
        f"[{description}] Expected '{expected_label}' but got '{label}' "
        f"for sender='{sender}', subject='{subject[:50]}'"
    )


@pytest.mark.parametrize(
    "sender,subject,body,expected_label,description",
    FYI_EMAILS,
    ids=[e[4] for e in FYI_EMAILS],
)
def test_fyi_classification(use_case, sender, subject, body, expected_label, description):
    """FYI emails should be classified as FYI."""
    email = make_email(sender=sender, subject=subject, body=body)
    # For CC'd emails, set is_cc=True
    is_cc = "CC'd" in description
    label = get_builtin_label(use_case, email, is_cc=is_cc)
    assert label == expected_label, (
        f"[{description}] Expected '{expected_label}' but got '{label}' "
        f"for sender='{sender}', subject='{subject[:50]}'"
    )


# ============================================================================
# SUMMARY TEST — counts to verify distribution
# ============================================================================


def test_distribution_counts():
    """Verify we have the expected test email counts.

    Counts updated 2026-04-25 : Telegram login code + Signal verification
    déplacés de NOISE → ACTION (step 0-verify, cf. cd630d67). NOISE -2,
    ACTION +2, total inchangé.
    """
    assert len(NOISE_EMAILS) == 496, f"Expected 496 Noise emails, got {len(NOISE_EMAILS)}"
    assert len(ACTION_EMAILS) == 314, f"Expected 314 Action emails, got {len(ACTION_EMAILS)}"
    assert len(FYI_EMAILS) == 210, f"Expected 210 FYI emails, got {len(FYI_EMAILS)}"
    total = len(NOISE_EMAILS) + len(ACTION_EMAILS) + len(FYI_EMAILS)
    assert total == 1020, f"Expected 1020 total emails, got {total}"
